<?php
namespace App\Console\Commands; use Illuminate\Console\Command; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Route; use Illuminate\Support\Facades\Schema;
class WarehouseV2FinanceCheckCommand extends Command{protected $signature='warehouse:v2-finance-check';protected $description='Validasi fondasi Finance Warehouse';public function handle():int{$tables=['wh_sales_invoices','wh_sales_invoice_items','wh_customer_receipts','wh_customer_receipt_allocations','wh_finance_events'];$missing=array_values(array_filter($tables,fn($x)=>!Schema::hasTable($x)));$routes=['api/v1/warehouse/finance/dashboard','api/v1/warehouse/finance/sales-invoices','api/v1/warehouse/finance/customer-receipts','api/v1/warehouse/finance/margin'];$registered=collect(Route::getRoutes())->map(fn($r)=>$r->uri())->all();$missingRoutes=array_values(array_filter($routes,fn($x)=>!in_array($x,$registered,true)));$duplicate=Schema::hasTable('wh_sales_invoices')?DB::table('wh_sales_invoices')->select('goods_receipt_id')->groupBy('goods_receipt_id')->havingRaw('COUNT(*) > 1')->count():0;$negative=Schema::hasTable('wh_sales_invoices')?DB::table('wh_sales_invoices')->where('balance_due','<',-0.0001)->count():0;$this->table(['Check','Result'],[['Missing tables',$missing?implode(', ',$missing):'-'],['Missing routes',$missingRoutes?implode(', ',$missingRoutes):'-'],['Duplicate invoice per GR',$duplicate],['Negative balance',$negative],['Status',(!$missing&&!$missingRoutes&&!$duplicate&&!$negative)?'PASSED':'FAILED']]);return(!$missing&&!$missingRoutes&&!$duplicate&&!$negative)?self::SUCCESS:self::FAILURE;}}